(()=>{const $=s=>document.querySelector(s),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};let cursor=null;
async function call(path,data){const r=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const p=await r.json();if(!r.ok)throw Error(p.error||'unavailable');return p}
async function summary(){const s=await call('/api/manage/summary');$('#delivery-health').textContent=s.deliveryConfigured?'Notification delivery is configured. Failed attempts remain in the queue for retry.':'Enquiries are saved. Automatic email delivery needs a configured provider.';const box=$('#metrics');box.replaceChildren();for(const stat of [...s.states.map(x=>[x.status,x.count]),...s.notifications.filter(x=>['failed','unconfigured'].includes(x.status)).map(x=>['Delivery '+x.status,x.count]),...s.funnel.map(x=>[x.event.replaceAll('_',' '),x.count])]){const c=el('article',undefined,'metric');c.append(el('strong',stat[1]),el('span',stat[0]));box.append(c)}}
async function load(more=false){try{$('#manage-message').textContent='Loading…';const q=new URLSearchParams({status:$('#status-filter').value});if(more&&cursor)q.set('before',cursor);const data=await call('/api/manage/leads?'+q);if(!more)$('#lead-list').replaceChildren();for(const lead of data.leads){const card=el('article',undefined,'lead-record');const title=el('h2',lead.id+' · '+(lead.name||lead.email||lead.phone));card.append(title,el('p',new Date(lead.created_at).toLocaleString()+' · '+lead.lead_status+' · Notification: '+lead.notification_status));const dl=el('dl',undefined,'summary');for(const [key,value] of Object.entries(lead.payload)){if(!value||key==='consent')continue;const row=el('div');row.append(el('dt',key.replaceAll('_',' ')),el('dd',typeof value==='object'?JSON.stringify(value):value));dl.append(row)}const details=el('details');details.append(el('summary','View request details'),dl);card.append(details);const form=el('form');const label=el('label','Follow-up status'),select=el('select');for(const status of ['new','contacted','qualified','quoted','closed']){const o=el('option',status);o.value=status;o.selected=status===lead.lead_status;select.append(o)}label.append(select);const noteLabel=el('label','Internal note'),note=el('textarea');note.maxLength=2000;note.value=lead.follow_up_note||'';noteLabel.append(note);const save=el('button','SAVE STATUS','button');save.type='submit';const msg=el('p');msg.setAttribute('role','status');form.append(label,noteLabel,save,msg);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await call('/api/manage/status',{id:lead.id,status:select.value,note:note.value});msg.textContent='Saved';await summary()}catch{msg.textContent='Could not save. Your note is still here.'}finally{save.disabled=false}};card.append(form);if(lead.notification_status==='failed'){const retry=el('button','RETRY NOTIFICATION','button outline');retry.onclick=async()=>{retry.disabled=true;try{await call('/api/manage/retry',{id:lead.id});msg.textContent='Retry processed. Refresh to see delivery status.'}catch(e){msg.textContent=e.message==='delivery_unconfigured'?'Configure a delivery provider first.':'Retry could not complete.'}finally{retry.disabled=false}};card.append(retry)}$('#lead-list').append(card)}cursor=data.next;$('#more').hidden=!cursor;$('#manage-message').textContent=data.leads.length?'':'No enquiries in this view.';await summary()}catch{$('#manage-message').textContent='Unable to load enquiries. Check your owner sign-in and retry.'}}
$('#refresh').onclick=()=>load();$('#status-filter').onchange=()=>load();$('#more').onclick=()=>load(true);load();})();
